  test.setTimeout(90_000);
  const links = [
  "https://the-internet.herokuapp.com/abtest",
  "https://the-internet.herokuapp.com/add_remove_elements/",
  "https://the-internet.herokuapp.com/basic_auth",
  "https://the-internet.herokuapp.com/broken_images",
  "https://the-internet.herokuapp.com/canvas",
  "https://the-internet.herokuapp.com/challenging_dom",
  "https://the-internet.herokuapp.com/checkboxes",
  "https://the-internet.herokuapp.com/context_menu"
];
  const broken: string[] = [];
  for (const url of links) {
    try {
      const response = await page.request.get(url, { maxRedirects: 5, timeout: 10_000 });
      const status = response.status();
      if (status >= 400 && status !== 401 && status !== 403) {
        broken.push(`${status} ${url}`);
      }
    } catch (err) {
      broken.push(`ERR ${url}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  expect(broken).toEqual([]);
});

