import { test, expect } from '@playwright/test';

test('Page loads without uncaught JavaScript errors', async ({ page }) => {
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  const response = await page.goto("https://practicetestautomation.com/practice-test-login/");
  expect(response?.status() ?? 0).toBeLessThan(400);
  await expect(page).toHaveTitle(new RegExp("Test Login \\| Practice Test Automation"));
  await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => undefined);
  expect(errors).toEqual([]);
});

import { test, expect } from '@playwright/test';

test('Linked pages respond without errors', async ({ page }) => {
  test.setTimeout(90_000);
  const links = [
  "https://practicetestautomation.com/",
  "https://practicetestautomation.com/practice/",
  "https://practicetestautomation.com/courses/",
  "https://practicetestautomation.com/workshop",
  "https://practicetestautomation.com/blog/",
  "https://practicetestautomation.com/contact/",
  "https://practicetestautomation.com/privacy-policy/"
];
  const broken: string[] = [];
  for (const url of links) {
    try {
      const response = await page.request.get(url, { maxRedirects: 5, timeout: 10_000 });
      const status = response.status();
      if (status >= 400 && status !== 401 && status !== 403) {
        broken.push(`${status} ${url}`);
      }
    } catch (err) {
      broken.push(`ERR ${url}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  expect(broken).toEqual([]);
});

