import { test, expect } from '@playwright/test';

test("Login button disabled state", async ({ page }) => {
  await page.goto("https://www.saucedemo.com/");
  await expect(page.getByRole("button", { name: "Login" })).toBeEnabled();
});

import { test, expect } from '@playwright/test';

test("Page reload retains login form visibility", async ({ page }) => {
  await page.goto("https://www.saucedemo.com/");
  await page.reload();
  await expect(page.getByRole("textbox", { name: "Username" })).toBeVisible();
  await expect(page.getByPlaceholder("Password")).toBeVisible();
});

import { test, expect } from '@playwright/test';

test('Page loads without uncaught JavaScript errors', async ({ page }) => {
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  const response = await page.goto("https://www.saucedemo.com/");
  expect(response?.status() ?? 0).toBeLessThan(400);
  await expect(page).toHaveTitle(new RegExp("Swag Labs"));
  await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => undefined);
  expect(errors).toEqual([]);
});
